INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0001', 'The token of Aero, a spot trading exchange formed from Aerodrome and Velodrome.', 'The exchange offers only spot swaps and liquidity pools. Stakers share trading fees, which is permissible.', 'You may hold, buy, sell, stake and use it. Provide liquidity only in pools of permissible tokens.', 'Old Aerodrome tokens convert one-to-one to the new token through the official upgrade page.', 'You may hold, buy, sell and use this token. Use it only in permissible activities.', '{"statusLabel":"Halal","usageLine":"You may hold, buy, sell and use this token. Use it only in permissible activities.","tiles":[],"activity":{"hold":"Yes","buySell":"Yes","payments":"Yes","rewards":"Vote fees allowed","lend":"No (riba)","liquidity":"Yes, in pools that do not lend deposits; avoid lending-based pools"}}');
