INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0003', 'The coin of Akash, a network where people rent out and rent computing power, mainly for AI.', 'It is used to pay for computing services. Nothing in its design or direction involves interest, gambling or other prohibited business.', 'You may hold, buy, sell and use it. Avoid interest-bearing lending and leveraged trading on it.', 'The coin is moving to the Solana network one-for-one. The ruling carries over unless its design changes.', 'You may hold, buy, sell and use this token. Use it only in permissible activities.', '{"statusLabel":"Halal","usageLine":"You may hold, buy, sell and use this token. Use it only in permissible activities.","tiles":[],"activity":{"hold":"Yes","buySell":"Yes","payments":"Yes","rewards":"Yes, if rewards come from validation and you keep ownership; no, if deposits are lent","lend":"No (riba)","liquidity":"Yes, in pools that do not lend deposits; avoid lending-based pools"}}');
