INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0004', 'The coin of Algorand, a general-purpose blockchain used for payments, apps and tokenized assets.', 'It is used to pay fees and secure the network. Haram apps built on the chain by others do not affect the coin itself.', 'You may hold, buy, sell and use it. Avoid lending it at interest and avoid interest-based products on the chain.', 'The network''s foundation promotes tokenized bonds and funds. A Shariah Scholar has confirmed this does not affect the coin, because the coin''s value does not depend on those products.', 'You may hold, buy, sell and use this token. Use it only in permissible activities.', '{"statusLabel":"Halal","usageLine":"You may hold, buy, sell and use this token. Use it only in permissible activities.","tiles":[],"activity":{"hold":"Yes","buySell":"Yes","payments":"Yes","rewards":"Yes, if rewards come from validation and you keep ownership; no, if deposits are lent","lend":"No (riba)","liquidity":"Yes, in pools that do not lend deposits; avoid lending-based pools"}}');
