INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0005', 'The coin of Aptos, a blockchain aimed at payments, finance and apps.', 'The chain is general-purpose. Its team backs a leveraged futures exchange, but that is one product among many, and plans to tie the coin to it are only a proposal.', 'You may hold, buy, sell and use it. Do not use futures or leveraged trading, and do not lend it at interest.', 'Native staking rewards are permissible. The ruling will be checked again if plans to tie the coin to futures trading go ahead.', 'You may hold, buy, sell and use this token. Use it only in permissible activities.', '{"statusLabel":"Halal","usageLine":"You may hold, buy, sell and use this token. Use it only in permissible activities.","tiles":[],"activity":{"hold":"Yes","buySell":"Yes","payments":"Yes","rewards":"Yes, if rewards come from validation and you keep ownership; no, if deposits are lent","lend":"No (riba)","liquidity":"Yes, in pools that do not lend deposits; avoid lending-based pools"}}');
