INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0010', 'The coin of Berachain, a blockchain built around decentralized finance.', 'The coin pays fees and secures the network. The team''s own products include an interest-based lending market, but this does not change the coin''s ruling; only those products must be avoided.', 'You may hold, buy, sell and use it. Do not use the network''s lending markets, do not put its stablecoin to work for yield, and avoid leveraged trading.', 'A small part of what stakers earn comes from lending apps; this is incidental and does not affect the ruling. The network''s stablecoin is a separate asset.', 'You may hold, buy, sell and use this token. Use it only in permissible activities.', '{"statusLabel":"Halal","usageLine":"You may hold, buy, sell and use this token. Use it only in permissible activities.","tiles":[],"activity":{"hold":"Yes","buySell":"Yes","payments":"Yes","rewards":"Yes, if rewards come from validation and you keep ownership; no, if deposits are lent","lend":"No (riba)","liquidity":"Yes, in pools that do not lend deposits; avoid lending-based pools"}}');
