INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0011', 'The token of the Binance exchange and the fee coin of BNB Chain.', 'Binance is a general exchange. It offers some non-permissible products, but no income from them is paid to holders.', 'You may hold, buy, sell and use it. Do not use futures, margin, interest-earning products, or airdrops that require depositing into them.', 'Binance suffered a large hack in October 2026 and has pledged to repay users.', 'You may hold, buy, sell and use this token. Use it only in permissible activities.', '{"statusLabel":"Halal","usageLine":"You may hold, buy, sell and use this token. Use it only in permissible activities.","tiles":[],"activity":{"hold":"Yes","buySell":"Yes","payments":"Yes","rewards":"Vote fees allowed","lend":"No (riba)","liquidity":"Yes, in pools that do not lend deposits; avoid lending-based pools"}}');
