INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0027', 'The coin of Decred, a blockchain whose holders vote on its rules and spending.', 'Its staking rewards are paid for voting on blocks and rules, not interest, and it has no link to prohibited activity.', 'You may hold, buy, sell and use it. Avoid lending it at interest and leveraged trading.', 'A software flaw was exploited in August 2026 and fixed within days.', 'You may hold, buy, sell and use this token. Use it only in permissible activities.', '{"statusLabel":"Halal","usageLine":"You may hold, buy, sell and use this token. Use it only in permissible activities.","tiles":[],"activity":{"hold":"Yes","buySell":"Yes","payments":"Yes","rewards":"Yes, if rewards come from validation and you keep ownership; no, if deposits are lent","lend":"No (riba)","liquidity":"Yes, in pools that do not lend deposits; avoid lending-based pools"}}');
