INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0040', 'A digital dollar issued by Paxos and distributed through a network of partner firms.', 'USDG is treated as money. It pays its holders nothing, so holding it does not involve interest. Paxos shares the interest on its reserves with partner firms; those rewards are a separate matter and are not halal.', 'You may hold, buy, sell and send it. When you exchange it, settle both sides at once. Do not join USDG rewards or Earn programmes offered by platforms: those payments come from interest.', 'No concerns found.', 'You may hold, buy, sell and use this token. Use it only in permissible activities.', '{"statusLabel":"Halal","usageLine":"You may hold, buy, sell and use this token. Use it only in permissible activities.","tiles":[],"activity":{"hold":"Yes","buySell":"Spot only; any agreed rate","payments":"Yes","rewards":"Interest-based rewards are not halal; promotional rewards from non-interest income are allowed","lend":"No (riba)","liquidity":"Yes, in pools that do not lend deposits; avoid lending-based pools"}}');
