INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0042', 'The coin of Hedera, a public network used for payments, tokenization and record-keeping, governed by a council of large companies.', 'It is used to pay network fees and to help secure the network. The promotion of tokenized financial assets on the network does not make the coin''s value depend on interest.', 'You may hold, buy, sell, use and stake it. Avoid interest-bearing lending and leveraged trading on it.', 'Some tokenized products on the network pay interest. They are separate assets; avoid them unless screened.', 'You may hold, buy, sell and use this token. Use it only in permissible activities.', '{"statusLabel":"Halal","usageLine":"You may hold, buy, sell and use this token. Use it only in permissible activities.","tiles":[],"activity":{"hold":"Yes","buySell":"Yes","payments":"Yes","rewards":"Yes, if rewards come from validation and you keep ownership; no, if deposits are lent","lend":"No (riba)","liquidity":"Yes, in pools that do not lend deposits; avoid lending-based pools"}}');
