INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0047', 'The coin of the Internet Computer, a network that runs apps, websites and AI services directly on-chain.', 'It is used to pay for computing and to vote on how the network is run. Nothing in its design or direction involves interest, gambling or other prohibited business.', 'You may hold, buy, sell and use it. You may lock it to vote on governance and receive the network''s voting rewards. Avoid interest-bearing lending and leveraged trading on it.', 'Locked coins take months or years to unlock, depending on the period you choose.', 'You may hold, buy, sell and use this token. Use it only in permissible activities.', '{"statusLabel":"Halal","usageLine":"You may hold, buy, sell and use this token. Use it only in permissible activities.","tiles":[],"activity":{"hold":"Yes","buySell":"Yes","payments":"Yes","rewards":"Yes, if rewards come from validation and you keep ownership; no, if deposits are lent","lend":"No (riba)","liquidity":"Yes, in pools that do not lend deposits; avoid lending-based pools"}}');
