INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0060', 'The coin of MANTRA, a network built to bring real-world assets such as property and investment funds onchain.', 'Almost everything actually placed on the network so far is backed by government debt, which earns interest. The halal assets it promotes, such as property, are minor or not yet live.', 'Avoid holding or trading it. Use it only incidentally, for example to pay a network fee or when a swap routes through it. Do not use the interest-bearing products on the network.', 'Its price collapsed in 2025 amid unproven allegations, and the network was hacked in 2026.', 'Avoid holding or trading it. Use it only incidentally or out of need, for example when a DEX routes a swap through it.', '{"statusLabel":"Doubtful","usageLine":"Avoid holding or trading it. Use it only incidentally or out of need, for example when a DEX routes a swap through it.","tiles":[],"activity":{"hold":"Avoid","buySell":"Avoid","payments":"Incidental only","rewards":"Avoid","lend":"No","liquidity":"Avoid"}}');
