INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0062', 'The token of MegaETH, a very fast network built on top of Ethereum for trading apps, games and consumer apps.', 'The token is used to secure and run a general-purpose network. Some of the income used to buy back the token comes from an interest-earning stablecoin, but this is incidental to the token''s value.', 'You may hold, buy, sell and use it. Do not use the network''s interest-earning stablecoin or its yield vaults, do not lend the token at interest, and avoid leveraged trading.', 'The network is young, and much of the money on it sits in one family of stablecoins.', 'You may hold, buy, sell and use this token. Use it only in permissible activities.', '{"statusLabel":"Halal","usageLine":"You may hold, buy, sell and use this token. Use it only in permissible activities.","tiles":[],"activity":{"hold":"Yes","buySell":"Yes","payments":"Yes","rewards":"Yes, if rewards come from validation and you keep ownership; no, if deposits are lent","lend":"No (riba)","liquidity":"Yes, in pools that do not lend deposits; avoid lending-based pools"}}');
