INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0076', 'The coin of Plasma, a blockchain built for sending and spending digital dollars.', 'The team''s main money app is built around an interest-based earn feature, and most activity on the chain is interest-based lending. The coin''s value is driven by these products.', 'Avoid holding or trading it. Use it only incidentally, for example to pay a network fee or when a swap routes through it. Do not use the earn feature, lending or yield vaults.', 'Most activity on this chain is interest-based lending, so check any product before using it.', 'Avoid holding or trading it. Use it only incidentally or out of need, for example when a DEX routes a swap through it.', '{"statusLabel":"Doubtful","usageLine":"Avoid holding or trading it. Use it only incidentally or out of need, for example when a DEX routes a swap through it.","tiles":[],"activity":{"hold":"Avoid","buySell":"Avoid","payments":"Incidental only","rewards":"Avoid","lend":"No","liquidity":"Avoid"}}');
