INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0077', 'The coin of Plume, a blockchain built to bring real-world financial assets onchain.', 'Almost everything offered on Plume is interest-based debt, such as loans, credit pools and government debt. Halal assets on it are minor.', 'Avoid holding or trading it. Use it only incidentally, for example to pay a network fee. Do not use its yield vaults, borrowing or lending products.', 'The asset mix may change; this ruling will be checked if halal assets grow.', 'Avoid holding or trading it. Use it only incidentally or out of need, for example when a DEX routes a swap through it.', '{"statusLabel":"Doubtful","usageLine":"Avoid holding or trading it. Use it only incidentally or out of need, for example when a DEX routes a swap through it.","tiles":[],"activity":{"hold":"Avoid","buySell":"Avoid","payments":"Incidental only","rewards":"Avoid","lend":"No","liquidity":"Avoid"}}');
