INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0078', 'The coin of Polkadot, a network that links many blockchains and now builds payments and messaging apps.', 'It pays network fees, secures the network through staking and is used for governance. Its value does not depend on interest, gambling or other prohibited business.', 'You may hold, buy, sell, use and stake it. Avoid interest-bearing lending of DOT and lending markets built on the network.', 'A bridge run by an outside team was hacked in 2026; native DOT was not affected.', 'You may hold, buy, sell and use this token. Use it only in permissible activities.', '{"statusLabel":"Halal","usageLine":"You may hold, buy, sell and use this token. Use it only in permissible activities.","tiles":[],"activity":{"hold":"Yes","buySell":"Yes","payments":"Yes","rewards":"Yes, if rewards come from validation and you keep ownership; no, if deposits are lent","lend":"No (riba)","liquidity":"Yes, in pools that do not lend deposits; avoid lending-based pools"}}');
