INSERT OR IGNORE INTO public_fields (ruling_id, what, why, how, know, usage_line, card_json) VALUES ('MIG-SCCF-0079', 'The coin of Polygon, a blockchain built for payments and moving money.', 'Most of the network''s fees come from a prediction market, which is a form of betting. The coin leans too closely on that activity to be called clean.', 'Avoid holding or trading it. Use it only incidentally, for example to pay a network fee. Do not use prediction markets, betting apps or interest-bearing lending.', 'If prediction markets leave the network, this ruling will be checked again.', 'Avoid holding or trading it. Use it only incidentally or out of need, for example when a DEX routes a swap through it.', '{"statusLabel":"Doubtful","usageLine":"Avoid holding or trading it. Use it only incidentally or out of need, for example when a DEX routes a swap through it.","tiles":[],"activity":{"hold":"Avoid","buySell":"Avoid","payments":"Incidental only","rewards":"Avoid","lend":"No","liquidity":"Avoid"}}');
